closeAskAuthNotification(name) {
  if (!name) {
    return;
  }

  const notificationBox = this.globalBox;
  const notification = notificationBox.getNotificationWithValue(
    `ask-auth-${name}`
  );
  if (!notification) {
    return;
  }

  notificationBox.removeNotification(notification);
},
